class Solution {
  public long maxSum(int[][] grid, int[] limits, int k) {
    int total = 0;
    for (int lim : limits) total += lim;
    int[] vals = new int[total];
    int p = 0;
    for (int i = 0; i < grid.length; i++) {
      int[] row = grid[i].clone();
      java.util.Arrays.sort(row);
      for (int t = 0; t < limits[i]; t++) vals[p++] = row[row.length - 1 - t];
    }
    java.util.Arrays.sort(vals);
    long sum = 0;
    for (int t = 0; t < k; t++) sum += vals[total - 1 - t];
    return sum;
  }
}
